input.command:
mkdir -p /tmp/check && cd /tmp/check && cat > check.cs <<'EOF'
#:project /travail/Atm/Atm.csproj
using Atm;
long total = 0, bad = 0, withdrawOnly = 0;
Denomination?[] jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
int[] amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
for (int b = 0; b <= 250; b += 5) for (int w = 0; w <= 200; w += 10)
for (int f = 0; f < 6; f++) for (int t = 0; t < 6; t++) for (int n = 0; n < 6; n++)
foreach (var j in jams) foreach (var a in amounts) {
  total++;
  var stock = new NoteCounts(f, t, n);
  var r = new CashMachine(new MoneyDispenser(stock, j)).Execute(new(b, w), new Operation.Withdraw(a));
  var fee = a > 100 ? 5 : 0;
  bool insufficient = a > 0 && a % 10 == 0 && w + a <= 200 && a + fee > b;
  if (insufficient && r.Status != AtmStatus.InsufficientFunds) { bad++; if (bad == 1) Console.WriteLine($"ex: solde {b}, retiré {w}, stock {stock}, bloquée {j}, retrait {a} -> {r.Status}"); }
}
Console.WriteLine($"{bad} retraits faux sur {total}");
EOF
dotnet run check.cs 2>&1 | tail -3

